import{_ as s,a0 as i,w as u,s as d,I as n,x as l,a1 as p,A as e,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"Recoll:Unix和Linux桌面的文本搜索工具 | LCTT x X-CMD","titleTemplate":false,"description":"Recoll:Unix和Linux桌面的文本搜索工具 | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Recoll:Unix和Linux桌面的文本搜索工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Recoll:Unix和Linux桌面的文本搜索工具 | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/Recoll--Text Search Tool For Unix And Linux Desktops","title":"Recoll:Unix和Linux桌面的文本搜索工具","tag":"201312","desc":""},"relativePath":"201312/Recoll--Text Search Tool For Unix And Linux Desktops.md","filePath":"[post].md"}'),g={name:"201312/Recoll--Text Search Tool For Unix And Linux Desktops.md"};function a(x,t,m,T,R,f){const o=i("Link");return u(),d("div",null,[t[22]||(t[22]=n("h1",{id:"recoll-unix和linux桌面的文本搜索工具",tabindex:"-1"},[l("Recoll:Unix和Linux桌面的文本搜索工具 "),n("a",{class:"header-anchor",href:"#recoll-unix和linux桌面的文本搜索工具","aria-label":"Permalink to “Recoll:Unix和Linux桌面的文本搜索工具”"},"​")],-1)),n("p",null,[p(o,{href:"http://www.recoll.org/"},{default:e(()=>[...t[0]||(t[0]=[l("Recoll",-1)])]),_:1}),t[1]||(t[1]=l("是一个Unix和Linux桌面的文本搜索工具。Recoll可以搜索文件名和文件内的关键字。",-1))]),t[23]||(t[23]=r(`<p>Recoll可以为你做到以下这些。</p><ul><li>它可以搜索任何格式的文件</li><li>支持通配符</li><li>可以依据文件的作者、类型、大小和格式等条件进行搜索</li><li>可以搜索存储在任何位置的文件，例如文件、归档文件、邮件附件等</li><li>支持桌面和网站集成</li><li>具备火狐插件，可索引web页的历史</li><li>点击一下搜索结果就可以在本地编辑器内打开或者显示文本预览</li><li>它是免费的开源的，在GPL许可下发布</li></ul><p>###在Ubuntu/Linux Mint上安装Recoll</p><p>Recoll在Ubuntu仓库里可以找到。然而，最好添加Recoll的仓库以便安装最新版本。</p><p>使用以下命令添加Recoll仓库：</p><pre><code>sudo add-apt-repository
</code></pre><p>使用命令更新软件列表：</p><pre><code>sudo apt-get update
</code></pre><p>现在就可以使用下面的命令安装Recoll。</p><pre><code>sudo apt-get install recoll
</code></pre>`,10)),n("p",null,[t[3]||(t[3]=l("对于其它的发行版，可以去",-1)),p(o,{href:"http://www.lesbonscomptes.com/recoll/download.html"},{default:e(()=>[...t[2]||(t[2]=[l("下载页面",-1)])]),_:1}),t[4]||(t[4]=l("下载源代码并编译安装。",-1))]),t[24]||(t[24]=r(`<p>###启动Recoll</p><p>Recoll可以从Dash或者菜单中启动。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Menu_0014.jpg" alt=""></p><p>第一次启动时，你需要索引整个home目录。依据你 home 目录里储存的东西的多少,需要的时间不等。按下<strong>Start indexing now</strong>按钮开始索引。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Recoll_002.jpg" alt=""></p><p>假如你想更多的自定义索引，可以调整索引配置和索引计划。要做到这一点，只需要点击一下<strong>Indexing configuration</strong>或者<strong>Indexing schedule</strong>链接。假如你要稍后再去配置，你可以在Preferences(首选项)菜单里配置这些选项。</p><p>一旦索引完成，你就可以搜索文件/文件夹了。结果将根据相关性展现，并显示匹配的一小部分内容。</p><p>###配置</p><p>正如上面提到的，假如你想更多的控制索引的细节，你可以调节Recoll的索引功能。 在Recoll的工具中有两个配置项</p><ol><li>索引配置</li><li>索引计划</li></ol><p>让我们来看一下上面这两个的简短描述。</p><p><strong>索引配置</strong>可以让你索引时决定包含哪些目录以及排除哪些目录。默认情况下索引时将包含整个home目录。你可以在这儿从索引中添加或移除目录。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/home-sk-.recoll-_003.jpg" alt=""></p><p>你也可以定义web历史队列以及储存web页面的最大容量。</p><p><strong>index schedule</strong>则是可以让制定一个计划以便于进行自动索引或者当你登陆系统后就进行实时索引。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Index-scheduling-setup_004.jpg" alt=""></p><p>Recoll支持两种索引计划：</p><p><strong>Cron任务</strong> - 决定什么时候开始运行以及写入Crontab键值。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Cron-Dialog_006.jpg" alt=""></p><p>以上这个屏幕截图中，Recoll的cron任务会在每天上午12点的时候执行。设置完cron任务后，点击enable键激活它就可以咯。</p><p><strong>启动时实时索引</strong> - 决定是否当你登陆入系统时进行实时索引。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Real-time-indexing-automatic-start_007.jpg" alt=""></p><p>激活这一选项，recoll的守护程序都会随系统启动。要注意的是这一选项只有在默认索引设置的情况下才可用。</p><p>###基本搜索</p><p>现在你已经对Recoll了解的足够多了。是时候去搜索一下文件或者文件夹了。这个应用的美妙之处就在于它既可以搜索文件名还可以搜索文件内的关键词。</p><p>在Recoll的用户界面中，在顶部右边的搜索栏中键入要搜索的关键字，然后点击Search按钮。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Recoll_008.jpg" alt=""></p><p>如你在上图所见，精确相关的内容将会显示还能预览到一小部分内容。你可以点击Open按钮直接打开搜索到的文件，或者在打开它之前使用预览按钮预览它。</p><p>你还可以过滤搜索结果，使用分类例如媒体、消息、其它、演示文档、电子表格或者文本等。更重要的是，你还可以选择匹配任一项、全部项、文件名或者语言等的搜索结果。</p><p>###高级搜索</p><p>点击菜单栏中的高级搜索图标或者前往<strong>Tools-&gt;Advanced Search</strong>。这将打开一个新的对话窗口。在这儿你可以附加更多的限制条件来进行搜索。例如我可以搜索文件内容里含有关键字“hp”以及文件名含有“storage”的文件。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Recoll_008.jpg" alt=""></p><p>这将找到并显示文件内含有关键字“hp”且文件名含有“storage”的文件。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Recoll_012.jpg" alt=""></p><p>###Unity桌面以及网站集成</p><p>这个应用支持桌面集成以及网站集成。假如你要把它集成到你的Ubuntu的Unity桌面中去，你可以用下面的命令安装<strong>recoll-lens</strong>。</p><pre><code>sudo apt-get install recoll-lens
</code></pre><p>请注意，lens限制显示结果最多显示20条。假如你要显示更多数目的搜索结果，编辑<strong>rclsearch.py</strong>，修改“<strong>if actual_results &gt;= 20:</strong>”这一行就可以咯。</p>`,38)),n("p",null,[t[6]||(t[6]=l("假如你使用火狐浏览器，要去搜索你每天访问的浏览历史，你可以使用这个",-1)),p(o,{href:"http://sourceforge.net/projects/recollfirefox/"},{default:e(()=>[...t[5]||(t[5]=[l("火狐扩展",-1)])]),_:1}),t[7]||(t[7]=l("。这个火狐扩展可以和Recoll一起工作去索引你全天浏览的网站。在安装完这个扩展之后，在Recoll的索引配置中从web历史标签页中激活它就可以咯。",-1))]),t[25]||(t[25]=n("p",null,[n("img",{src:"http://180016988.r.cdn77.net/wp-content/uploads/2013/11/home-sk-.recoll-_013.jpg",alt:""})],-1)),t[26]||(t[26]=n("p",null,"所有的Linux都在他们的文件管理器中内建了搜索功能，以便于尽可能容易的搜索文件/文件夹。对于那些不满足于内置搜索功能并想寻找更高级文本搜索工具的人来说，Recoll是个值得一试的工具。我认为，这真是个容易使用且功能强大的工具，对基本搜索如此，对高级搜索也是如此.",-1)),t[27]||(t[27]=n("p",null,"欢呼吧！",-1)),n("p",null,[t[9]||(t[9]=l("如有问题，请参考我们的Q/A论坛 : ",-1)),p(o,{href:"http://ask.unixmen.com/"},{default:e(()=>[...t[8]||(t[8]=[l("http://ask.unixmen.com/",-1)])]),_:1}),t[10]||(t[10]=l(" 。",-1))]),t[28]||(t[28]=n("hr",null,null,-1)),n("p",null,[t[12]||(t[12]=l("via: ",-1)),p(o,{href:"http://www.unixmen.com/recoll-text-searching-tool-linux-desktops/"},{default:e(()=>[...t[11]||(t[11]=[l("http://www.unixmen.com/recoll-text-searching-tool-linux-desktops/",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=l("译者：",-1)),p(o,{href:"https://github.com/Linux-pdz"},{default:e(()=>[...t[13]||(t[13]=[l("Linux-pdz",-1)])]),_:1}),t[16]||(t[16]=l(" 校对：",-1)),p(o,{href:"https://github.com/jasminepeng"},{default:e(()=>[...t[14]||(t[14]=[l("jasminepeng",-1)])]),_:1})]),n("p",null,[t[19]||(t[19]=l("本文由 ",-1)),p(o,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[17]||(t[17]=[l("LCTT",-1)])]),_:1}),t[20]||(t[20]=l(" 原创翻译，",-1)),p(o,{href:"http://linux.cn/"},{default:e(()=>[...t[18]||(t[18]=[l("Linux中国",-1)])]),_:1}),t[21]||(t[21]=l(" 荣誉推出",-1))])])}const C=s(g,[["render",a]]);export{L as __pageData,C as default};
